//! THE FLOAT ORACLE (plans/float.md, "The semantics and their authority"):
//! the community's TAS tools' exact state after every update of a playback,
//! replayed through `FloatRefEngine` and compared field by field, BIT for bit.
//! - UniversalClassicTas (`tools/uct/exact.lua`, regenerated by `rewrite
//!   golden uct` into `gates/uct/`): the IL load, its seeds.
//! - Celia (`tools/celia/exact.lua`, `rewrite golden celia` into
//!   `gates/celia/`): the loading jank, its seeds.
//!
//! A trace is the tool's whole cart, the original one; the traced program
//! lacks its draw-only objects and some fields. So every object of OURS is
//! matched, in order, with the tool's of the same type, and every number and
//! boolean OURS holds must be the tool's, exactly.

use std::collections::BTreeMap;

use anyhow::{anyhow, bail, ensure, Context, Result};
use celeste_core::arith::Float;
use celeste_core::lua_f64::LuaF64;

use crate::trace::heap::Value;
use crate::trace::iface::{self, Step};
use crate::trace::refdomain::RefDomain;
use crate::engines::reference::FloatRefEngine;
use crate::trace::state::State;

/// A scalar of a trace: a double's bits, or a boolean. OURS may also be a
/// range: a field an unseeded `rnd` wrote (`UNSEEDED`).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Scalar {
    Num(u64),
    Bool(bool),
    Range(u64, u64),
}

/// The fields a tool leaves to an UNSEEDED `rnd` that the traced program
/// keeps: a chest's `x` while it shakes (`start - 1 + rnd(3)`; only its last
/// shake, where the berry appears, is seeded: `cart::tool_seeds`). Ours is
/// the range, the tool's value must lie in it.
const UNSEEDED: &[(&str, &str)] = &[("chest", "x")];

impl std::fmt::Display for Scalar {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Scalar::Num(b) => write!(f, "{:?} ({b:#018x})", f64::from_bits(*b)),
            Scalar::Bool(b) => write!(f, "{b}"),
            Scalar::Range(lo, hi) => write!(f, "[{:?}, {:?}]", f64::from_bits(*lo), f64::from_bits(*hi)),
        }
    }
}

#[derive(Debug, Default)]
pub struct Update {
    /// The input the update consumed (`None`: before the player's first
    /// frame, when UCT's file has none yet: no button is held; Celia's are
    /// the buttons its cart saw, always).
    pub input: Option<u8>,
    pub globals: BTreeMap<String, Scalar>,
    /// `objects`, in order: each object's type and its fields by path.
    pub objects: Vec<(String, BTreeMap<String, Scalar>)>,
}

use crate::tools::golden::{hexfloat, DRAW_ONLY};

fn scalar(s: &str) -> Result<Scalar> {
    Ok(match s {
        "true" => Scalar::Bool(true),
        "false" => Scalar::Bool(false),
        _ => Scalar::Num(hexfloat(s)?.to_bits()),
    })
}

/// A trace (`tools/uct/exact.lua`'s format), the draw-only objects dropped.
pub fn parse_trace(text: &str) -> Result<Vec<Update>> {
    let mut out: Vec<Update> = Vec::new();
    let mut drop = false;
    for (i, line) in text.lines().enumerate() {
        let at = || format!("trace line {}: {line:?}", i + 1);
        let mut w = line.split(' ');
        match w.next() {
            Some("u") => {
                let parts: Vec<&str> = w.collect();
                let [_, "kf", _, "in", input] = parts.as_slice() else { bail!("{}", at()) };
                let input: i32 = input.parse().with_context(at)?;
                out.push(Update { input: (input >= 0).then(|| input as u8), ..Default::default() });
            }
            // A sound: the state is what is compared.
            Some("s") => {}
            Some("g") => {
                let (Some(name), Some(v)) = (w.next(), w.next()) else { bail!("{}", at()) };
                out.last_mut().ok_or_else(|| anyhow!("{}: before any update", at()))?.globals.insert(name.to_string(), scalar(v).with_context(at)?);
            }
            Some("o") => {
                let (Some(_), Some(ty)) = (w.next(), w.next()) else { bail!("{}", at()) };
                drop = DRAW_ONLY.contains(&ty);
                if !drop {
                    out.last_mut().ok_or_else(|| anyhow!("{}: before any update", at()))?.objects.push((ty.to_string(), BTreeMap::new()));
                }
            }
            Some("f") => {
                let (Some(path), Some(v)) = (w.next(), w.next()) else { bail!("{}", at()) };
                if !drop {
                    let u = out.last_mut().ok_or_else(|| anyhow!("{}: before any update", at()))?;
                    let (_, fields) = u.objects.last_mut().ok_or_else(|| anyhow!("{}: a field before any object", at()))?;
                    fields.insert(path.to_string(), scalar(v).with_context(at)?);
                }
            }
            Some("") | None => {}
            Some(_) => bail!("{}", at()),
        }
    }
    Ok(out)
}

type FState = State<RefDomain<Float>>;

fn ours(v: &Value<RefDomain<Float>>) -> Option<Scalar> {
    match v {
        Value::Num(iv) => Some(match iv.as_point() {
            Some(n) => Scalar::Num(LuaF64::to_bits(n)),
            None => Scalar::Range(iv.lo.to_bits(), iv.hi.to_bits()),
        }),
        Value::Bool(b) => Some(Scalar::Bool(*b)),
        _ => None,
    }
}

/// Every number and boolean of a table, by path (`spd.x`), the `type`
/// reference and functions left out, as `exact.lua` walks the tool's.
fn fields(st: &FState, table: crate::trace::heap::TableId, prefix: &str, out: &mut BTreeMap<String, Scalar>) {
    let tab = &st.heap.tables[&table];
    for (k, v) in &tab.hash {
        if k == "type" {
            continue;
        }
        let path = if prefix.is_empty() { k.clone() } else { format!("{prefix}.{k}") };
        match v {
            Value::Table(t) => fields(st, *t, &path, out),
            v => {
                if let Some(s) = ours(v) {
                    out.insert(path, s);
                }
            }
        }
    }
}

fn type_name(st: &FState, t: crate::trace::heap::TableId) -> Option<String> {
    st.heap.tables[&st.globals].hash.iter().find_map(|(k, v)| (*v == Value::Table(t) && k != "objects").then(|| k.clone()))
}

/// Our objects, in order: type and fields.
pub fn our_objects(st: &FState) -> Result<Vec<(String, BTreeMap<String, Scalar>)>> {
    let Some(Value::Table(objects)) = iface::get(st, &[iface::key("objects")]) else { bail!("no `objects`") };
    let mut out = Vec::new();
    for (i, o) in st.heap.tables[&objects].arr.iter().enumerate() {
        let Value::Table(t) = o else { continue };
        let Some(Value::Table(ty)) = st.heap.tables[t].hash.get("type") else { bail!("objects[{i}]: no type") };
        let name = type_name(st, *ty).ok_or_else(|| anyhow!("objects[{i}]: a type no global names"))?;
        let mut f = BTreeMap::new();
        fields(st, *t, "", &mut f);
        out.push((name, f));
    }
    Ok(out)
}

/// The globals a trace records that the traced program holds.
fn our_global(st: &FState, name: &str) -> Option<Scalar> {
    let path: Vec<Step> = name.split('.').map(iface::key).collect();
    iface::get(st, &path).and_then(|v| ours(&v))
}

/// Whether `w`'s double lies in our range `v`.
fn contains(v: Scalar, w: u64) -> bool {
    let Scalar::Range(lo, hi) = v else { return false };
    (f64::from_bits(lo)..=f64::from_bits(hi)).contains(&f64::from_bits(w))
}

/// Our state against the tool's after one update: every object of ours (in
/// order, by type) and each of its numbers and booleans, and the recorded
/// globals we hold. A range of ours passes only where it is `UNSEEDED`'s and
/// holds the tool's value.
pub fn compare(st: &FState, u: &Update) -> Result<()> {
    for (name, theirs) in &u.globals {
        if let Some(mine) = our_global(st, name) {
            ensure!(mine == *theirs, "global {name}: ours {mine}, the tool's {theirs}");
        }
    }
    let mine = our_objects(st)?;
    let (a, b): (Vec<&str>, Vec<&str>) = (mine.iter().map(|(t, _)| t.as_str()).collect(), u.objects.iter().map(|(t, _)| t.as_str()).collect());
    ensure!(a == b, "the objects differ: ours {a:?}, the tool's {b:?}");
    for (i, ((ty, f), (_, g))) in mine.iter().zip(&u.objects).enumerate() {
        for (path, v) in f {
            match g.get(path) {
                Some(w) if w == v => {}
                Some(&Scalar::Num(w)) if contains(*v, w) && UNSEEDED.contains(&(ty.as_str(), path.as_str())) => {}
                Some(w) => bail!("objects[{i}] ({ty}).{path}: ours {v}, the tool's {w}"),
                // An absent field the traced program writes as 0 (the
                // widening table's exact `AbsentAsZero`: the cart tells nil
                // from 0 only by raising).
                None if *v == Scalar::Num(0) && celeste_engine::widening::absent_as_zero().any(|(t, a)| t == ty && a == path) => {}
                None => bail!("objects[{i}] ({ty}).{path}: ours {v}, the tool has no such field"),
            }
        }
    }
    Ok(())
}

/// Replay a trace's inputs from the engine's start, one concrete frame per
/// update, comparing every state; returns the updates compared. The update
/// that leaves the room is the tool's last (its driver quits there): ours
/// must leave on it, and only the room is compared.
pub fn replay(eng: &mut FloatRefEngine, trace: &[Update]) -> Result<usize> {
    let mut st = eng.start_state().clone();
    let room = |s: &FState| (our_global(s, "room.x"), our_global(s, "room.y"));
    let start = room(&st);
    for (n, u) in trace.iter().enumerate() {
        let mut leaves = eng.frame_states(&st, u.input.unwrap_or(0)).with_context(|| format!("update {n}"))?;
        ensure!(leaves.len() == 1, "update {n}: {} successors of a concrete frame (an unseeded rnd?)", leaves.len());
        st = leaves.remove(0);
        // The frame's garbage goes (else every frame clones all before it).
        st.gc();
        if room(&st) != start {
            ensure!(n + 1 == trace.len(), "update {n}: we left the room, the tool played on to update {}", trace.len() - 1);
            return Ok(n + 1);
        }
        compare(&st, u).with_context(|| format!("update {n} (input {:?})", u.input))?;
    }
    Ok(trace.len())
}

#[cfg(test)]
mod tests {
    use super::*;

    use crate::settings::FloatTool;

    /// THE FLOAT ORACLE IS UNIVERSALCLASSICTAS, BIT FOR BIT: every golden of
    /// gates/uct/manifest.txt (the tasdatabase's files as UCT plays them, as
    /// they are: the cart buffers a jump as the original does) replayed from
    /// the IL load under the file's seeds, every number and boolean equal
    /// after every update (`jbuffer` and `p_jump` among them).
    #[test]
    #[ignore = "slow, ./check.sh t2 runs it: every UCT golden, ~30 CPU-s"]
    fn the_float_engine_plays_every_golden_as_uct_does() {
        replay_all(FloatTool::Uct);
    }

    /// AND IT IS CELIA, BIT FOR BIT: every golden of gates/celia/manifest.txt
    /// (the same files as Celia plays them: `rewrite golden celia`) replayed
    /// from Celia's start (its loading jank `J`, its seeds).
    #[test]
    #[ignore = "slow, ./check.sh t2 runs it: every Celia golden, ~30 CPU-s"]
    fn the_float_engine_plays_every_golden_as_celia_does() {
        replay_all(FloatTool::Celia);
    }

    /// Every golden of the tool's manifest, replayed in parallel on the
    /// differential harness (`check::differential`): every update of every
    /// golden compared (one SKIPPED fails it too), and at least one.
    fn replay_all(tool: FloatTool) {
        use crate::check::differential::{run, verdict, Ran};
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("gates").join(tool_dir(tool));
        let manifest = std::fs::read_to_string(dir.join("manifest.txt")).unwrap_or_else(|e| panic!("{}: {e}", dir.join("manifest.txt").display()));
        let lines: Vec<&str> = manifest.lines().filter(|l| !l.trim().is_empty()).collect();
        let done = run(16, lines.len(), || Ok(()), |_, i| replay_golden(&dir, lines[i], tool).map_err(|e| e.context(lines[i].to_string()))).unwrap_or_else(|e| panic!("{e:#}"));
        let (mut compared, mut skipped) = (0usize, Vec::new());
        for (r, line) in done.into_iter().zip(&lines) {
            match r {
                Ran::Done(n) => compared += n,
                Ran::Skipped(why) => skipped.push(format!("{line}: {why}")),
            }
        }
        eprintln!("[{}] {} goldens, {compared} updates compared", tool_dir(tool), lines.len());
        verdict(compared, skipped.len(), || format!("goldens SKIPPED: {}", skipped.join("; "))).unwrap_or_else(|e| panic!("{e:#}"));
    }

    fn tool_dir(tool: FloatTool) -> &'static str {
        match tool {
            FloatTool::Uct => "uct",
            FloatTool::Celia => "celia",
        }
    }

    /// One manifest line: its trace replayed; the updates compared.
    fn replay_golden(dir: &std::path::Path, line: &str, tool: FloatTool) -> Result<usize> {
        let w: Vec<&str> = line.split_whitespace().collect();
        let (cat, level) = (w[0], w[1]);
        let field = |k: &str| w.iter().find_map(|x| x.strip_prefix(&format!("{k}="))).ok_or_else(|| anyhow!("no {k}="));
        let (x, y) = field("room")?.split_once(',').ok_or_else(|| anyhow!("room"))?;
        let seeds = field("seeds")?;
        // Celia's start is its IL load's jank, the default (the manifest's
        // J, from `rewrite room`'s starts, must be it).
        let loading_jank = match tool {
            FloatTool::Uct => None,
            FloatTool::Celia => {
                let j = crate::starts::celia_jank((x.parse()?, y.parse()?))?;
                ensure!(j.map_or("-".to_string(), |j| j.to_string()) == field("jank")?, "Celia's J {j:?} is not the manifest's");
                j
            }
        };
        let s = crate::settings::Settings {
            arith: crate::settings::Arith::Float(tool),
            room: (x.parse()?, y.parse()?),
            // The run's dash count is all its replay depends on (the
            // manifest's categories include our own `random0`, ...).
            category: if field("gemskip")? == "1" { crate::settings::Category::GemskipAny } else { crate::settings::Category::Any },
            // The tool's run: always seeded (every seed 0 without a list).
            balloon_seeds: Some(if seeds == "-" { String::new() } else { seeds.to_string() }),
            loading_jank,
            ..Default::default()
        };
        let bytes = std::fs::read(dir.join(format!("{cat}_{level}.trace.zst")))?;
        let text = String::from_utf8(zstd::decode_all(&bytes[..])?)?;
        let trace = parse_trace(&text)?;
        ensure!(trace.len() == field("updates")?.parse::<usize>()?, "the trace's updates are not the manifest's");
        let mut eng = FloatRefEngine::new(&s)?;
        replay(&mut eng, &trace)
    }

    /// THE FIXED-POINT WITNESS EXITS IN 16.16: the gemskip 100% 2500m (116)
    /// witness, whose goldens DIE in both tools, leaves the room in the fixed
    /// reference engine from the same IL load (the file's first input on the
    /// player's first frame) - so the goldens' death is the arithmetic's, and
    /// the float engine reproduces it.
    #[test]
    fn the_fixed_point_witnesses_exit_in_fixed_point() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
        exits_in_fixed_point(&root.join("gates/witnesses/gemskip100_TAS25.tas"), "gemskip100", 25).unwrap_or_else(|e| panic!("{e:#}"));
    }

    /// A witness file (`[seeds]inputs`, the tools' format) of category `cat`
    /// at `level` leaves its room on its last input in the FIXED reference
    /// engine, from the IL load: some lineage, where an unseeded `rnd` (a
    /// chest's shake, which no file seeds in 16.16) forks the frame, and
    /// none before the last input.
    fn exits_in_fixed_point(path: &std::path::Path, cat: &str, level: i16) -> Result<()> {
        use crate::engines::reference::RefEngine;
        let category = cat.parse().map_err(|e| anyhow!("{}: {e}", path.display()))?;
        let text = std::fs::read_to_string(path).with_context(|| path.display().to_string())?;
        let (Some(seeds), inputs) = crate::concrete::parse_tas(&text)? else { bail!("{}: not [seeds]inputs", path.display()) };
        let room = crate::game_runner::room_of_level(level);
        let s = crate::settings::Settings { room, category, balloon_seeds: Some(seeds.join(",")), ..Default::default() };
        let mut eng = RefEngine::new(&s)?;
        let mut sts = vec![eng.start_state().clone()];
        let at = |st: &State<RefDomain>| (iface::get(st, &[iface::key("room"), iface::key("x")]), iface::get(st, &[iface::key("room"), iface::key("y")]));
        let start = at(&sts[0]);
        let (mut k, mut frames) = (0usize, 0u32);
        let exited = loop {
            // The spawn's timing is every lineage's (no `rnd` before it).
            let player = !crate::trace::widen::objects_of_type(&sts[0], "player").is_empty();
            let input = if player { inputs.get(k).copied() } else { Some(0) };
            let Some(input) = input else { break false };
            k += usize::from(player);
            frames += 1;
            let mut next = Vec::new();
            for st in &sts {
                next.extend(eng.frame_states(st, input)?);
            }
            ensure!(next.len() <= 64, "{}: frame {frames}: {} lineages", path.display(), next.len());
            for st in &mut next {
                st.gc();
            }
            if next.iter().any(|st| at(st) != start) {
                break true;
            }
            sts = next;
        };
        ensure!(exited && k == inputs.len(), "{}: the fixed engine {} after {k} of {} inputs (frame {frames})", path.display(), if exited { "exited" } else { "did not exit" }, inputs.len());
        Ok(())
    }

    /// Our UNSUBMITTED routes' goldens and witnesses, never committed (our
    /// unsubmitted and teased routes are never revealed): the local store of
    /// `rewrite golden uct local all` and `rewrite golden celia local all`.
    const LOCAL_GOLDENS: &str = "/var/tmp/float-goldens";

    /// THE LOCAL GOLDENS: each tool's goldens of our unsubmitted witnesses
    /// replay as the committed ones do, and every local witness leaves its room
    /// in the fixed engine. The store is the machine's (`./check.sh local` runs
    /// this); where it is absent the test says SKIPPED on its output, which
    /// nextest shows and check.sh repeats: never a silent pass.
    #[test]
    #[ignore = "local, ./check.sh local runs it: reads the machine-local store /var/tmp/float-goldens"]
    fn the_local_goldens() {
        let base = std::path::Path::new(LOCAL_GOLDENS);
        let read = |p: &std::path::Path| match std::fs::read_to_string(p) {
            Ok(t) => Some(t),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                println!("[local goldens] SKIPPED: {} is absent (our unsubmitted routes live only in {LOCAL_GOLDENS}, never in the repo)", p.display());
                None
            }
            Err(e) => panic!("{}: {e}", p.display()),
        };
        let entries = |t: &str| -> Vec<Vec<String>> { t.lines().filter(|l| !l.trim().is_empty() && !l.starts_with('#')).map(|l| l.split_whitespace().map(str::to_string).collect()).collect() };
        for tool in [FloatTool::Uct, FloatTool::Celia] {
            let dir = base.join(tool_dir(tool));
            let Some(m) = read(&dir.join("manifest.txt")) else { continue };
            let lines: Vec<&str> = m.lines().filter(|l| !l.trim().is_empty()).collect();
            let n: usize = lines.iter().map(|line| replay_golden(&dir, line, tool).unwrap_or_else(|e| panic!("{}: {line}: {e:#}", dir.display()))).sum();
            println!("[local goldens] {}: {} goldens, {n} updates compared", tool_dir(tool), lines.len());
            assert!(!lines.is_empty() && n > 0, "{}: no local golden compared anything", dir.display());
        }
        if let Some(t) = read(&base.join("witnesses/witnesses.txt")) {
            let ws = entries(&t);
            for w in &ws {
                let [_, cat, level, file] = &w[..] else { panic!("a local witness line {w:?}: KEY CATEGORY LEVEL FILE") };
                exits_in_fixed_point(&base.join(file), cat, level.parse().expect("a level")).unwrap_or_else(|e| panic!("{e:#}"));
            }
            println!("[local goldens] witnesses: {} leave their rooms in fixed point", ws.len());
        }
    }

    #[test]
    fn hex_floats_parse_exactly() {
        for v in [0.1f64, -0.5, 1.0 / 3.0, 0.0, 123.456, -3.5355339059327378, 1e-10] {
            let s = format!("{}0x{}", if v < 0.0 { "-" } else { "" }, hex_of(v.abs()));
            assert_eq!(hexfloat(&s).unwrap().to_bits(), v.to_bits(), "{s}");
        }
        assert_eq!(hexfloat("-0x0p+0").unwrap().to_bits(), (-0.0f64).to_bits());
        assert_eq!(hexfloat("0x1.999999999999ap-4").unwrap(), 0.1);
    }

    /// `%a` of a positive normal double (or 0), as LuaJIT prints it.
    fn hex_of(v: f64) -> String {
        if v == 0.0 {
            return "0p+0".into();
        }
        let b = v.to_bits();
        let (e, m) = (((b >> 52) & 0x7ff) as i32 - 1023, b & ((1 << 52) - 1));
        let frac = format!("{m:013x}");
        let frac = frac.trim_end_matches('0');
        if frac.is_empty() {
            format!("1p{e:+}")
        } else {
            format!("1.{frac}p{e:+}")
        }
    }
}
